import React from 'react';
import { Target, Info, CheckCircle } from 'lucide-react';

/**
 * Hypothesis Testing Tab - Statistical hypothesis testing and significance analysis
 */
export default function HypothesisTestingTab() {
  return (
    <div className="px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center mb-4">
          <Target className="h-8 w-8 text-red-500 mr-3" />
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Hypothesis Testing
          </h1>
        </div>
        <p className="text-lg text-gray-600 dark:text-gray-300">
          Perform statistical hypothesis tests to determine significance and make data-driven decisions.
        </p>
      </div>

      {/* Coming Soon Notice */}
      <div className="bg-gradient-to-br from-purple-50 to-violet-50 dark:from-purple-900/10 dark:to-violet-900/10 rounded-2xl p-8 border border-purple-200 dark:border-purple-800/30 text-center">
        <div className="inline-flex items-center justify-center w-16 h-16 bg-purple-100 dark:bg-purple-900/30 rounded-full mb-6">
          <CheckCircle className="h-8 w-8 text-purple-600 dark:text-purple-400" />
        </div>
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-4">
          Coming Soon
        </h2>
        <p className="text-gray-600 dark:text-gray-300 mb-6 max-w-2xl mx-auto">
          This comprehensive hypothesis testing toolkit will include calculators and guides for:
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-4xl mx-auto text-left">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">One-Sample Tests</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• One-sample t-test</li>
              <li>• One-sample z-test</li>
              <li>• One-sample proportion test</li>
              <li>• Wilcoxon signed-rank test</li>
            </ul>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">Two-Sample Tests</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• Independent t-test</li>
              <li>• Paired t-test</li>
              <li>• Two-sample z-test</li>
              <li>• Mann-Whitney U test</li>
            </ul>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">ANOVA</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• One-way ANOVA</li>
              <li>• Two-way ANOVA</li>
              <li>• Repeated measures ANOVA</li>
              <li>• Kruskal-Wallis test</li>
            </ul>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">Chi-Square Tests</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• Goodness of fit test</li>
              <li>• Test of independence</li>
              <li>• Test of homogeneity</li>
              <li>• McNemar's test</li>
            </ul>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">Correlation Tests</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• Pearson correlation</li>
              <li>• Spearman correlation</li>
              <li>• Kendall's tau</li>
              <li>• Partial correlation</li>
            </ul>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">Power Analysis</h3>
            <ul className="text-sm text-gray-600 dark:text-gray-300 space-y-1">
              <li>• Sample size calculation</li>
              <li>• Power calculation</li>
              <li>• Effect size estimation</li>
              <li>• Type I and II errors</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Test Process Overview */}
      <div className="mt-8 bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Hypothesis Testing Process
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-lg mb-3">
              <span className="text-lg font-bold text-blue-600 dark:text-blue-400">1</span>
            </div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-2">State Hypotheses</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Define null and alternative hypotheses
            </p>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-green-100 dark:bg-green-900/30 rounded-lg mb-3">
              <span className="text-lg font-bold text-green-600 dark:text-green-400">2</span>
            </div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-2">Choose Test</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Select appropriate statistical test
            </p>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-orange-100 dark:bg-orange-900/30 rounded-lg mb-3">
              <span className="text-lg font-bold text-orange-600 dark:text-orange-400">3</span>
            </div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-2">Calculate</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Compute test statistic and p-value
            </p>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-purple-100 dark:bg-purple-900/30 rounded-lg mb-3">
              <span className="text-lg font-bold text-purple-600 dark:text-purple-400">4</span>
            </div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-2">Conclude</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Make decision and interpret results
            </p>
          </div>
        </div>
      </div>

      {/* Information Box */}
      <div className="mt-8 bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800/30 rounded-lg p-4">
        <div className="flex items-start">
          <Info className="h-5 w-5 text-amber-600 dark:text-amber-400 mt-0.5 mr-3 flex-shrink-0" />
          <div>
            <h3 className="font-semibold text-amber-800 dark:text-amber-200 mb-1">
              Development Status
            </h3>
            <p className="text-sm text-amber-700 dark:text-amber-300">
              This tool will provide step-by-step guidance through the hypothesis testing process,
              with automatic test selection, assumption checking, and detailed interpretation of results.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
